export function toAetherusHandoff(event){if(!event?.eventId||!event?.type)throw new TypeError('eventId/type required');return{schemaVersion:'earthus-aetherus-bridge.v1',eventId:event.eventId,type:event.type,occurredAt:event.occurredAt??null,objectIds:[...new Set(event.objectIds??[])],sourceRefs:[...new Set(event.sourceRefs??[])],earthusSceneRef:event.earthusSceneRef??null,rule:'HANDOFF_ONLY_DO_NOT_MERGE_RUNTIME_OWNERSHIP'};}
